```python
def enhanced_char_count(s):
    """
    This function counts letters, digits, and special characters in a word, 
    tracks the frequency of each vowel and consonant, 
    identifies the highest and lowest frequency characters, 
    and categorizes characters into letters, digits, and special characters.

    Example:
    >>> enhanced_char_count("a1b2c3d4e")
    {'Letters': {'Vowels': {'a': 1, 'e': 1}, 'Consonants': {'b': 1, 'c': 1, 'd': 1}, 'Special characters': 0},
     'Digits': {'1': 1, '2': 1, '3': 1, '4': 1},
     'Highest frequency': {'a': 1}, 'Lowest frequency': {'b': 1, 'c': 1, 'd': 1, 'e': 1},
     'Categorization': {'Letters': 5, 'Digits': 4, 'Special characters': 0}}
    """

    char_counts = {'Letters': {'Vowels': {}, 'Consonants': {}}, 'Digits': {}, 'Special characters': 0}
    highest_frequency = None
    lowest_frequency = None

    for char in s:
        if char.isalpha():
            char_counts['Letters'][char.lower()][char] += 1
            if char not in char_counts['Letters']['Vowels']:
                char_counts['Letters']['Vowels'][char] = 1
        elif char.isdigit():
            char_counts['Digits'][char] += 1
        else:
            char_counts['Special characters'] += 1

        if char not in char_counts['Letters']['Consonants']:
            char_counts['Letters']['Consonants'][char] = 1

        if char_counts[char] > highest_frequency:
            highest_frequency = char
        if char_counts[char] < lowest_frequency or lowest_frequency is None:
            lowest_frequency = char

    char_counts['Categorization'] = {'Letters': len(char_counts['Letters']['Vowels']) + len(char_counts['Letters']['Consonants']), 'Digits': len(char_counts['Digits']), 'Special characters': char_counts['Special characters']}

    char_counts['Highest frequency'] = highest_frequency
    char_counts['Lowest frequency'] = lowest_frequency

    return char_counts
```

