```php
function validatePassword($password) {
    $length = strlen($password);
    $uppercase = false;
    $lowercase = false;
    $digit = false;
    $specialChar = false;

    if ($length < 8) {
        return false;
    }

    for ($i = 0; $i < $length; $i++) {
        if (ctypeUpper($password[$i])) {
            $uppercase = true;
        } elseif (ctypeLower($password[$i])) {
            $lowercase = true;
        } elseif (is_numeric($password[$i])) {
            $digit = true;
        } elseif (in_array($password[$i], ['!', '@', '#', '$', '%', '^', '&', '*'])) {
            $specialChar = true;
        }
    }

    return $uppercase && $lowercase && $digit && $specialChar;
}
```

**Usage:**

