```java
import java.util.*;

public class CharacterFrequency {

    public static HashMap<Character, Integer> getCharacterFrequency(String str, char ch) {
        HashMap<Character, Integer> frequency = new HashMap<>();

        int count = 0;
        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == ch) {
                count++;
                frequency.put(ch, count);
            }
        }

        int sequenceCount = 1;
        for (int i = 1; i < str.length(); i++) {
            if (str.charAt(i) == ch && str.charAt(i - 1) == ch) {
                sequenceCount++;
                frequency.put(ch, frequency.get(ch) + sequenceCount);
            } else {
                sequenceCount = 1;
            }
        }

        return frequency;
    }

    public static void main(String[] args) {
        String str = "Hello World";
        char ch = 'l';

        HashMap<Character, Integer> frequency = getCharacterFrequency(str, ch);

        System.out.println("Character Frequency:\n");
        frequency.forEach((k, v) -> System.out.println(k + ": " + v));
    }
}
```

**Fixed Bugs:**

- The reference code did not track repeated sequences of the character.
- The code did not handle the case where the character being searched is not found in the string.
- The code did not return the frequency of the character in the form of a hashmap.

