using System;
using System.Threading.Tasks;

namespace PyramidVolumeCalculator
{
    class Program
    {
        static void Main(string[] args)
        {
            // Initialize variables
            double height, baseLength, baseWidth;

            // Display menu options
            Console.WriteLine("Choose a calculation method:");
            Console.WriteLine("1. Sequential");
            Console.WriteLine("2. Asynchronous");
            int choice = int.Parse(Console.ReadLine());

            // Obtain measurement values
            Console.Write("Enter the height: ");
            height = double.Parse(Console.ReadLine());
            Console.Write("Enter the base length: ");
            baseLength = double.Parse(Console.ReadLine());
            Console.Write("Enter the base width: ");
            baseWidth = double.Parse(Console.ReadLine());

            // Perform calculation based on user choice
            switch (choice)
            {
                case 1:
                    CalculateVolumeSequentially(height, baseLength, baseWidth);
                    break;
                case 2:
                    CalculateVolumeAsynchronously(height, baseLength, baseWidth).Wait();
                    break;
            }
        }

        private static void CalculateVolumeSequentially(double height, double baseLength, double baseWidth)
        {
            double volume = (height * baseLength * baseWidth) / 3;
            Console.WriteLine("Volume of the pyramid: {0}", volume);
        }

        private static async Task CalculateVolumeAsynchronously(double height, double baseLength, double baseWidth)
        {
            await Task.Run(() =>
            {
                double volume = (height * baseLength * baseWidth) / 3;
                Console.WriteLine("Volume of the pyramid: {0}", volume);
            });
        }
    }
}
```

