<!DOCTYPE html>
<html>
<head>
  <title>Dynamic Table</title>
  <script src="https://ajax.googleapis.com/ajax/libs/jquery/3.6.0/jquery.min.js"></script>
  <style>
    table {
      border-collapse: collapse;
    }

    th, td {
      padding: 8px;
      border: 1px solid black;
    }
  </style>
</head>
<body>

  <table id="data-table">
    <thead>
      <tr>
        <th>Id</th>
        <th>First Name</th>
        <th>Last Name</th>
        <th>Age</th>
        <th>Email</th>
      </tr>
    </thead>
    <tbody id="tbody"></tbody>
  </table>

  <div id="pagination">
    <button id="prev">Previous</button>
    <button id="next">Next</button>
  </div>

  <input type="text" id="search" placeholder="Search...">

  <script>
    // Data source
    var data = [
      { id: 1, firstName: 'John', lastName: 'Doe', age: 25, email: 'john.doe@example.com' },
      // ... 9 more rows of data
    ];

    // Initialize page size and offset
    var pageSize = 5;
    var offset = 0;

    // Function to create a table row
    function createRow(data) {
      var tr = $('<tr>');
      tr.append('<td>' + data.id + '</td>');
      tr.append('<td>' + data.firstName + '</td>');
      tr.append('<td>' + data.lastName + '</td>');
      tr.append('<td>' + data.age + '</td>');
      tr.append('<td>' + data.email + '</td>');
      return tr;
    }

    // Function to update the table
    function updateTable() {
      var searchTerm = $('#search').val();
      var sortedColumn = $('th.sorted').attr('data-sort');
      var sortOrder = $('th.sorted').hasClass('asc') ? 'asc' : 'desc';

      // Filter data based on search term
      var filteredData = data.filter(row => {
        for (var key in row) {
          if (row[key].toString().toLowerCase().includes(searchTerm.toLowerCase())) {
            return true;
          }
        }
        return false;
      });

      // Sort data based on sorted column and order
      filteredData.sort((a, b) => {
        if (sortedColumn === 'id') {
          return a.id - b.id;
        }
        // ... Implement sorting logic for other columns
      });

      // Paginate data
      var paginatedData = filteredData.slice(offset, offset + pageSize);

      // Clear and recreate tbody
      $('#tbody').html('');
      paginatedData.forEach(row => {
        $('#tbody').append(createRow(row));
      });
    }

    // Event listeners
    $('#search').keyup(updateTable);
    $('th').click(function() {
      $(this).toggleClass('sorted');
      updateTable();
    });

    $('#prev').click(function() {
      offset = offset - pageSize;
      updateTable();
    });

    $('#next').click(function() {
      offset = offset + pageSize;
      updateTable();
    });
  </script>
</body>
</html>
```

**Key Features:**

- Dynamic row addition/removal
