```c++
#include <iostream>
#include <vector>

using namespace std;

vector<long long> fibonacci(long long n, long long a = 0, long long b = 1) {
    vector<long long> fib;
    fib.push_back(a);
    fib.push_back(b);

    while (fib.back() < n) {
        long long next = fib.back() + fib[fib.size() - 2];
        fib.push_back(next);
    }

    return fib;
}

vector<long long> fibonacciBase(long long n, long long a, long long b, long long base) {
    vector<long long> fib;
    fib.push_back(a % base);
    fib.push_back(b % base);

    while (fib.back() < n) {
        long long next = (fib.back() + fib[fib.size() - 2]) % base;
        fib.push_back(next);
    }

    return fib;
}


int main() {
    long long n;
    cin >> n;

    vector<long long> fib = fibonacci(n);
    for (long long num : fib) {
        cout << num << " ";
    }
    cout << endl;

    long long a, b;
    cin >> a >> b;
    fib = fibonacciBase(n, a, b, 10);
    for (long long num : fib) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}
```

**Explanation:**

* The algorithm starts by defining a vector to store the Fibonacci sequence.
* It iterates until the last element in the sequence exceeds the given number n.
* To handle large Fibonacci numbers efficiently, it employs modular arithmetic by taking the remainder of each element by a given base.
* The time complexity of the algorithm is O(n), where n is the number of Fibonacci numbers to be calculated.

**Boundary Condition Handling:**

* The algorithm checks for overflow by comparing the last two elements of the Fibonacci sequence.
* If the sequence exceeds the boundary, it terminates the loop.

**Efficient Calculation:**

* By using modular arithmetic, the algorithm avoids storing large numbers in memory, thereby improving efficiency.

