function updateGreeting(language) {
  const greetingElement = document.getElementById('greeting');
  greetingElement.textContent = `Greetings, Universe! ${language}`;
}

// Backend (server.js)
const translate = require('google-translate');

app.get('/detectLanguage', async (req, res) => {
  const { language } = req.query;
  try {
    const translation = await translate('Greetings, Universe!', { to: language });
