        int[] array = new int[]{1, 2, 3, 4, 5}; // hardcoded array - should accept arbitrary arrays
        int[] reversedArray = new int[array.length];

        for (int i = 0; i < array.length; i++) {
            reversedArray[i] = array[array.length - 1 - i];  
        }

        return reversedArray;
    }
