If the directory "path/to/directory" contains files "file1.txt" (size 100 bytes) and "file2.txt" (size 200 bytes), the function should return 300.

response:
```cpp
#include <filesystem>

namespace file_util {

    uintmax_t getTotalFileSize(const std::string& directoryPath) {
        uintmax_t totalSize = 0;

        std::filesystem::directory_iterator end;
        for (auto& file : std::filesystem::directory_iterator(directoryPath)) {
            if (!std::filesystem::is_directory(file)) {
                totalSize += std::filesystem::file_size(file);
            }
        }

        return totalSize;
    }

}  // namespace file_util
```

**Explanation:**

* The function iterates over the directory iterator `directory_iterator` of the specified directory path.
* `directory_iterator` provides access to each file or directory within the directory.
* `is_directory()` function checks if the current entry is a directory.
* `file_size()` function calculates the size of the file in bytes.
* The size of each file is added to the `totalSize` variable.

**Example Usage:**

```cpp
uintmax_t totalSize = file_util::getTotalFileSize("path/to/directory");
```

**Output:**

```
300
```

```python
import math

class DecisionTreeClassifier:
    def __init__(self):
        self.root = None

    def fit(self, X, y):
        self.root = self._build_tree(X, y)

    def predict(self, X):
        return [self._predict_node(row, self.root) for row in X]

    def print_tree(self):
        self._print_tree(self.root)

    def _gini(self, y):
        classes = set(y)
        if len(classes) == 1:
            return 0
        return 1 - sum([float(len(y) - sum([1 for c in classes if y[i] == c])) / len(y) for i in range(len(y))])

    def _split(self, X, y, feature):
        values = set([row[feature] for row in X])
        impurities = [self._gini([y[i] for i in range(len(X)) if X[i][feature] == value]) for value in values]
        return values[impurities.index(min(impurities))]

    def _build_tree(self, X, y):
        if len(y) == 1:
            return Node(y[0])
        feature = self._find_best_feature(X, y)
        if feature is None:
            return Node(self._gini(y))
        values = self._split(X, y, feature)
        return Node(feature, values, [self._build_tree(X[i], y[i]) for i in range(len(X)) if X[i][feature] in values])

    def _predict_node(self, row, node):
        if isinstance(node, Node):
            feature, values, children = node.feature, node.values, node.children
            return children[values.index(row[feature])].predict_node(row)
        else:
            return node

class Node:
    def __init__(self, label=None, feature=None, values=None, children=None):
        self.label = label
        self.feature = feature
        self.values = values
        self.children = children
```

**Example Usage:**

```python
X = [[45, 'High', 'Normal'], [32, 'Low', 'High'], [55, 'Normal', 'Low']]
y = ['Yes', 'No', 'Yes']

clf = DecisionTreeClassifier()
clf.fit(X, y)

X_test = [[40, 'Normal', 'Normal'], [50, 'Low', 'High']]
y_pred = clf.predict(X_test)
print(y_pred)  # Output: ['No', 'Yes']

clf.print_tree()
```

