```python
import os
import subprocess

class Tmux:
    def __init__(self):
        if not self._tmux_available():
            print("Tmux is not installed.")
            exit()
        self.sessions = {}

    def _tmux_available(self):
        return "tmux" in os.environ["PATH"]

    def create(self, session_name):
        subprocess.run(["tmux", "new-session", "-s", session_name])
        self.sessions[session_name] = session_name

    def switch(self, session_name):
        subprocess.run(["tmux", "attach", "-t", session_name])

    def list(self):
        sessions = subprocess.run(["tmux", "list-sessions"], capture_output=True).stdout.decode().splitlines()
        print("Available sessions:")
        for session in sessions:
            print(session.strip())

    def exit(self):
        subprocess.run(["tmux", "kill-server"])
        exit()


if __name__ == "__main__":
    tmux = Tmux()

    while True:
        command, args = input("tmux> ").split()

        if command == "create":
            tmux.create(args[0])
        elif command == "switch":
            tmux.switch(args[0])
        elif command == "list":
            tmux.list()
        elif command == "exit":
            tmux.exit()
        else:
            print("Invalid command.")
```

**Example Usage:**

```
tmux> create my_session
tmux> list
Available sessions:
my_session
tmux> switch my_session
```

**Notes:**

- This program simulates the basic functionality of `tmux` and does not include all the features of the actual tool.
- The `subprocess` module is used to interact with the `tmux` command-line tool.
- The `capture_output=True` argument in `subprocess.run()` captures the output of the command for further processing.

