        payroll.addEmployee(new Employee("John Doe", 5000));
        payroll.addEmployee(new Employee("Jane Smith", 6000));
        payroll.addEmployee(new Employee("Mark Wilson", 7000));

        double totalPayroll = payroll.calculatePayroll();
        System.out.println("Total Payroll: $" + totalPayroll);

        payroll.printEmployeeDetails();
    }
