// user-info.component.ts

import { Component, OnInit } from '@angular/core';

const user = {
  id: 1,
  name: 'Bob',
  age: 23,
  email: 'bob@example.com'
};

@Component({
  selector: 'app-user-info',
  templateUrl: './user-info.component.html',
  styleUrls: ['./user-info.component.css']
})
export class UserInfoComponent implements OnInit {

  name: string = user.name;
  age: number = user.age;
  email: string = user.email;

  constructor() { }

  ngOnInit(): void { }

  editName() {
    this.name = '<input type="text" [(ngModel)]="name" name="name">';
  }

  editAge() {
    this.age = '<input type="number" [(ngModel)]="age" name="age">';
  }

  editEmail() {
    this.email = '<input type="email" [(ngModel)]="email" name="email">';
  }

  saveChanges() {
    // Client-side validation
    if (!this.validateForm()) {
      return;
    }

    // Server-side validation
    fetch('/api/users/update', {
      method: 'POST',
      body: JSON.stringify({ name: this.name, age: this.age, email: this.email })
    })
      .then(res => {
        if (res.ok) {
          // Update user information on the server
          user.name = this.name;
          user.age = this.age;
          user.email = this.email;
          console.log('User information updated successfully.');
        } else {
          console.error('Error updating user information.');
        }
      })
      .catch(error => {
        console.error('Error during server request:', error);
      });
  }

  // ...
}
```

