```typescript
import { Request, Response } from 'express';

const handler = (req: Request, res: Response) => {
  try {
    // Your server request logic goes here
    // ...

    // Send response
    res.status(200).send('Success!');
  } catch (error) {
    console.error(error); // Log error for debugging purposes
    res.status(500).send('Internal Server Error');
  }
};

export default handler;
```

**Error Handling Explanation:**

* If an error occurs during the server request process, the `catch` block is triggered.
* `console.error(error)` logs the error for debugging purposes.
* `res.status(500).send('Internal Server Error')` sends a generic 500 Internal Server Error response to the client.


