def generateStackComponent(component_name, force, interface, component_type):
    # Create the component directory
    component_dir = os.path.join('src', component_name)
    if os.path.exists(component_dir) and not force:
        print(f"Component '{component_name}' already exists. Use the '--force' flag to overwrite.")
        return

    os.mkdir(component_dir)

    # Generate interface file
    interface_file = os.path.join(component_dir, 'interface.ts')
    with open(interface_file, 'w') as f:
        f.write(f"""
import {component_type} from '@interfaces';

export interface {component_name} extends {component_type} {{
    // Interface properties specific to the component
}}
""")

    # Generate service/task file
    if component_type == 'service':
        service_file = os.path.join(component_dir, 'service.ts')
        with open(service_file, 'w') as f:
            f.write(f"""
import {component_name} from './{component_name}';

export const {component_name}: {component_name} = {component_name};
""")
    else:
        task_file = os.path.join(component_dir, 'task.ts')
        with open(task_file, 'w') as f:
            f.write(f"""
import {component_name} from './{component_name}';

export const run = async (): Promise<void> => {{
    // Task implementation
}};
""")
```

**Example Usage:**

```
generateStackComponent --component_name MyService --interface service --component_type service
```

**Output Directory Structure:**

```
src/MyService/
├── interface.ts
├── service.ts
```

