use std::{char, string};

const INTEGER_VALUES: &[i32] = &[1, 4, 5, 9, 10, 40, 50, 90, 100, 400, 500, 900, 1000, 4000];
const ROMAN_NUMERAL: &[char] = &['I', 'IV', 'V', 'IX', 'X', 'XL', 'L', 'XC', 'C', 'CD', 'D', 'CM', 'M', 'MMMM'];

fn int_to_ascii_roman(n: i32) -> i32 {
    let mut roman = String::new();
    let mut i = 13;

    while n > 0 {
        while n >= INTEGER_VALUES[i] {
            n -= INTEGER_VALUES[i];
            roman.push(ROMAN_NUMERAL[i]);
        }
        i -= 1;
    }

    roman.chars().fold(0usize, |acc, ch| acc + (ch as i32))
