```python
def can_arrange(arr):
    """Create a function which returns a dictionary containing the largest index of
    an element which is not greater than or equal to the element immediately preceding
    it and the index of the next smallest element that can be swapped with it to
    potentially correct the order. If no such element exists, return {'index': -1, 'swap_with': -1}.
    The given array will not contain duplicate values.

    Examples:
    can_arrange([1,2,4,3,5]) = {'index': 3, 'swap_with': 2}
    can_arrange([1,2,3]) = {'index': -1, 'swap_with': -1}
    """

    if len(arr) <= 1:
        return {'index': -1, 'swap_with': -1}

    index = -1
    swap_with = -1

    for i in range(len(arr)):
        if i > 0 and arr[i] < arr[index]:
            index = i

    if index == -1:
        return {'index': -1, 'swap_with': -1}

    for j in range(len(arr)):
        if j > index and arr[j] > arr[index] and arr[j] < arr[swap_with] or swap_with == -1:
            swap_with = j

    return {'index': index, 'swap_with': swap_with}
```

