```python
import requests

from requests_mock import Mock


class Events:
    def __init__(self, api_key):
        self.api_key = api_key


    def get(self, event_id, locale='en_US'):
        url = f'https://api.yelp.com/events/{event_id}?locale={locale}&limit=1'
        response = requests.get(url, headers={'Authorization': f'Bearer {self.api_key}'})
        return response.json()


    def search(self, location, categories=None, date_filter=None, radius=None):
        url = 'https://api.yelp.com/events/search'
        params = {
            'location': location,
            'limit': 50,
        }

        if categories:
            params['categories'] = ','.join(categories)

        if date_filter:
            params['date_filter'] = date_filter

        if radius:
            params['radius'] = radius

        response = requests.get(url, headers={'Authorization': f'Bearer {self.api_key}'}, params=params)
        return response.json()


def test_get_method():
    with Mock(requests.get) as mock:
        mock.return_value({'id': '123', 'name': 'Test Event'})
        events = Events('test_key')
        result = events.get('123')
        assert result['id'] == '123'


def test_search_method():
    with Mock(requests.get) as mock:
        mock.return_value([{'id': '456', 'name': 'Another Event'}])
        events = Events('test_key')
        result = events.search('San Francisco')
        assert len(result['events']) == 1
```

