```java
import java.util.*;

public class ArmstrongPrimeFinder {

    public static boolean isArmstrong(int num) {
        int originalNum = num;
        int sum = 0;
        int count = 0;

        while (num > 0) {
            count++;
            num /= 10;
        }

        num = originalNum;

        while (num > 0) {
            int digit = num % 10;
            sum += Math.pow(digit, count);
            num /= 10;
        }

        return sum == originalNum;
    }

    public static boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }

        if (num == 2) {
            return true;
        }

        return isPrime(num, 2);
    }

    private static boolean isPrime(int num, int i) {
        if (num % i == 0) {
            return false;
        }

        if (i >= Math.sqrt(num)) {
            return true;
        }

        return isPrime(num, i + 1);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter the range: ");
        int range = scanner.nextInt();

        System.out.println("Armstrong and Prime Numbers in the range: ");
        for (int i = 2; i <= range; i++) {
            if (isArmstrong(i) && isPrime(i)) {
                System.out.println(i);
            }
        }

        System.out.println("Sum of Prime Armstrong Numbers: " + getPrimeArmstrongSum(range));
    }

    private static int getPrimeArmstrongSum(int range) {
        int sum = 0;

        for (int i = 2; i <= range; i++) {
            if (isArmstrong(i) && isPrime(i)) {
                sum += i;
            }
        }

        return sum;
    }
}
```

