enum class Gender { Male, Female, Other };

class Student {
private:
    string name;
    int age;
    array<float, 3> grades;
    bool isGraduated;
    Gender gender;

    float calculateTotalScore() {
        // Specific calculation using age and average grade
        return age / 20.0f * grades.sum() / grades.size();
    }

public:
    Student(string name, int age, float grades[], bool isGraduated, Gender gender) {
        this->name = name;
        this->age = validateAge(age);
        for (int i = 0; i < 3; i++) {
            this->grades[i] = validateGrade(grades[i]);
        }
        this->isGraduated = isGraduated;
        this->gender = gender;
    }

    float calculateAverageGrade() {
        return grades.sum() / grades.size();
    }

    static void printStudentDetails(Student student) {
        cout << "Name: " << student.name << endl;
        cout << "Age: " << student.age << endl;
        cout << "Grades: ";
        for (float grade : student.grades) {
            cout << grade << " ";
        }
        cout << endl;
        cout << "Is Graduated: " << student.isGraduated << endl;
        cout << "Gender: " << static_cast<int>(student.gender) << endl;
    }

    bool isEligibleToGraduate() {
        return calculateAverageGrade() >= 80 && age >= 20;
    }

    float getFinalGrade() {
        return calculateFinalGrade();
    }

private:
    int validateAge(int age) {
        if (age < 17 || age > 30) {
            throw runtime_error("Age must be between 17 and 30.");
        }
        return age;
    }

    float validateGrade(float grade) {
        if (grade < 0 || grade > 100) {
            throw runtime_error("Grade must be between 0 and 100.");
        }
        return grade;
    }

    float calculateFinalGrade() {
        // Formula: final_grade = average_grade * (age / 20) * (number_of_subjects / 5)
        return calculateAverageGrade() * calculateTotalScore();
    }
};
