```java
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.io.IntWritable;
import org.apache.hadoop.io.Text;
import org.apache.hadoop.mapreduce.Job;
import org.apache.hadoop.mapreduce.Mapper;
import org.apache.hadoop.mapreduce.Reducer;

public class DiskSpaceAnalyzer {

    public static class DiskSpaceMapper extends Mapper<Object, Text, Text, IntWritable> {

        @Override
        public void map(Object key, Text value, Context context) throws IOException, InterruptedException {
            Path path = new Path(value.toString());
            long size = path.getFileSystem().getContentSummary(path).getUsed();
            context.write(new Text(path.toString()), new IntWritable(size));
        }
    }

    public static class DiskSpaceReducer extends Reducer<Text, IntWritable, Text, Text> {

        @Override
        public void reduce(Text key, Iterable<IntWritable> values, Context context) throws IOException, InterruptedException {
            int totalSize = 0;
            for (IntWritable value : values) {
                totalSize += value.get();
            }
            if (totalSize > 100000) { // Threshold to delete data
                context.write(key, new Text("Data exceeding threshold: " + totalSize));
            }
        }
    }

    public static void main(String[] args) throws Exception {
        Job job = Job.getInstance(args[0], "Disk Space Analyzer");
        job.setMapperClass(DiskSpaceMapper.class);
        job.setReducerClass(DiskSpaceReducer.class);
        job.setOutputKeyClass(Text.class);
        job.setOutputValueClass(IntWritable.class);
        job.waitForCompletion(true);
    }
}
```

**Explanation:**

* **DiskSpaceMapper** scans the HDFS directory specified by the input path and calculates the size of each file or directory. 
* **DiskSpaceReducer** receives the file paths and their sizes from the mapper and identifies those exceeding a predefined threshold (100000 in this example). 
* The reducer then writes the file paths of the large files to the output, indicating that they should be deleted. 

**To use:**

1. Run the `DiskSpaceAnalyzer` job with the input path to the HDFS directory you want to analyze.
2. Check the job output for a list of file paths exceeding the threshold.
3. Manually delete the files listed in the output.

```python
import turtle
from random import randint

class Snake:
    def __init__(self):
        self.segments = [turtle.Turtle() for _ in range(3)]
        self.direction = 'up'
        self.speed = 10

    def move(self):
        for segment in self.segments:
            segment.forward(self.speed)

    def up(self):
        self.direction = 'up'

    def down(self):
        self.direction = 'down'

    def left(self):
        self.direction = 'left'

    def right(self):
        self.direction = 'right'

class Food:
    def __init__(self):
        self.turtle = turtle.Turtle()
        self.turtle.shape('circle', radius=10)
        self.refresh()

    def refresh(self):
        self.turtle.goto(randint(-200, 200), randint(-200, 200))

class Score:
    def __init__(self):
        self.score = 0

    def increase(self):
        self.score += 1

    def reset(self):
        self.score = 0

def main():
    screen = turtle.Screen()
    screen.setup(width=400, height=400)
    screen.bgcolor('lightgrey')

    snake = Snake()
    food = Food()
    score = Score()

    while True:
        snake.move()

        if snake.segments[0].distance(food.turtle) < 10:
            food.refresh()
            score.increase()

        if snake.segments[0].xcor() < -200 or snake.segments[0].xcor() > 200 or snake.segments[0].ycor() < -200 or snake.segments[0].ycor() > 200:
            break

        for i in range(1, len(snake.segments)):
            if snake.segments[i].distance(snake.segments[0]) < 10:
                break

        screen.update()

if __name__ == "__main__":
    main()
```

