open class ProgressDispatcher: NSObject {

    fileprivate let dispatcher: Dispatcher<Progress, Progress, NSError>

    public init(dispatcher: Dispatcher<Progress, Progress, NSError>) {
        self.dispatcher = dispatcher
    }

    func updateProgress(_ progress: Progress) {
        dispatcher.dispatch(progress)
    }

    func updateError(_ error: NSError) {
        dispatcher.dispatch(Progress(), error: error)
    }
}
```

**Explanation:**

* The `updateProgress` method takes a `Progress` object and calls the `dispatch` method of the `dispatcher` with the progress value.
* The `updateError` method takes an `NSError` object and calls the `dispatch` method of the `dispatcher` with a `Progress` object and the error.
* The `ProgressDispatcher` class conforms to the `Dispatcher` protocol by implementing the required `dispatch` methods.

