#include <iostream>
#include <string>
#include <stdlib.h>

using namespace std;

int main() {
    string userChoice, computerChoice;
    int winner = 0;

    cout << "Enter your choice (rock, paper, or scissors): ";
    cin >> userChoice;

    // Convert user input to lowercase for case insensitivity
    userChoice = userChoice.ToLower();

    // Generate a random choice for the computer
    computerChoice = (rand() % 3) ? "rock" : (rand() % 3) ? "paper" : "scissors";

    // Compare choices and determine the winner
    if (userChoice == "rock" && computerChoice == "scissors") {
        winner = 1;
    } else if (userChoice == "scissors" && computerChoice == "paper") {
        winner = 1;
    } else if (userChoice == "paper" && computerChoice == "rock") {
        winner = 1;
    } else if (userChoice == computerChoice) {
        winner = 2; // Tie
    }

    // Display the outcome of the game
    cout << "You chose: " << userChoice << endl;
    cout << "Computer chose: " << computerChoice << endl;
    cout << "Outcome: ";
    switch (winner) {
        case 1:
            cout << "You win!" << endl;
            break;
        case 2:
            cout << "It's a tie!" << endl;
            break;
        default:
            cout << "You lose!" << endl;
    }

    cout << "Press any key to exit..." << endl;
    cin.get();
    return 0;
}
```

**Explanation:**

* The program prompts the user for their choice and reads their input into the `userChoice` variable.
* To handle case insensitivity, the user input is converted to lowercase using `userChoice = userChoice.ToLower()`.
* A random number is generated using the `rand()` function, and the corresponding choice is assigned to the `computerChoice` variable based on the remainder.
* The choices are compared, and the winner is determined based on the rules.
* The outcome of the game is displayed, including the user's choice, the computer's choice, and the winner or tie status.
* The program waits for the user to press a key before exiting.

