    public async Task<string> Run(string input)
    {
        // Authenticate to Azure
        var azure = new AzureFluent().WithSubscription("YOUR_SUBSCRIPTION_ID");

        // List all available services
        var services = new List<string>();
        foreach (var service in azure.Services().ListAll().Where(s => s.Name.Length > 0))
        {
            services.Add(service.Name);
        }

        // Identify incorrect codes
        var invalidCodes = services.Where(s => s.Contains("invalid") || s.Contains("typo")).ToList();

        // Randomly select one service for a code showcase
        var randomService = services.ElementAt(new Random().Next(services.Count));

        // Output results
        return $"**Available Services:**\n\n" +
               string.Join("\n", services) + "\n\n" +
               $"**Incorrect Codes:**\n\n" +
               string.Join("\n", invalidCodes) + "\n\n" +
               $"**Code Showcase Service:**\n\n" +
               randomService;
    }
}
