public class EmployeePayroll {

    public static void main(String[] args) {
        List<Employee> employees = Arrays.asList(
                new Employee("John Doe", 25, 3000),
                new Employee("Jane Smith", 28, 4000),
                new Employee("Mark Wilson", 32, 5000)
        );

