    static class Employee {
        private String name;
        private int age;
        private int salary;

        public Employee(String name, int age, int salary) {
            this.name = name;
            this.age = age;
            this.salary = salary;
        }

        public String getName() {
            return name;
        }

        public int getAge() {
            return age;
        }

        public int getSalary() {
            return salary;
        }
    }

    static class PayrollCalculator {

        public List<Payroll> calculatePayrolls(List<Employee> employees) {
            List<Payroll> payrolls = new ArrayList<>();

            for (Employee employee : employees) {
                Payroll payroll = new Payroll(employee, calculateSalary(employee));
                payrolls.add(payroll);
            }

            return payrolls;
        }

        private int calculateSalary(Employee employee) {
            // Calculate salary based on employee age and experience
            return employee.getSalary();
        }
    }

    static class Payroll {
        private Employee employee;
        private int salary;

        public Payroll(Employee employee, int salary) {
            this.employee = employee;
            this.salary = salary;
        }

        public Employee getEmployee() {
            return employee;
        }

        public int getSalary() {
            return salary;
        }
    }
}
