protocol MessagingProtocol {
    var sender: String { get }
    var recipient: String { get }
    var timestamp: Date { get }
    var content: String { get }

    func encryptContent(key: String) -> String
    func decryptContent(key: String, encryptedContent: String) -> String
}
```

```swift
extension MessagingProtocol {
    func encryptContent(key: String) -> String {
        let encryptedContent = String(
            aes.GCM.encrypt(
                contents: content.utf8,
                key: key.utf8,
                iv: [0] * 12
            )
        )
        return encryptedContent
    }

    func decryptContent(key: String, encryptedContent: String) -> String {
        let decryptedContent = String(
            aes.GCM.decrypt(
                encrypted: encryptedContent.utf8,
                key: key.utf8,
                iv: [0] * 12
            )
        )
        return decryptedContent
    }
}
```

**Sample Message Usage:**

