let message: MessagingProtocol = MessagingProtocol {
    sender = "sender@example.com"
    recipient = "recipient@example.com"
    timestamp = Date()
    content = "Hello, world!"
}

// Encrypt the message content
let encryptedContent = message.encryptContent(key: "secretKey")

// Decrypt the message content
let decryptedContent = message.decryptContent(key: "secretKey", encryptedContent: encryptedContent)

print(decryptedContent) // Output: "Hello, world!"
```

