class Employee:
    def __init__(self, name, experience, salary):
        self.name = name
        self.experience = experience
        self.salary = salary
        self.projects = []

    def add_project(self, project_name, duration, role):
        if project_name in [p['name'] for p in self.projects]:
            self.projects[self.projects.index(project_name)] = {'name': project_name, 'duration': duration, 'role': role}
        else:
            self.projects.append({'name': project_name, 'duration': duration, 'role': role})

    def get_total_experience(self):
        return sum([p['duration'] for p in self.projects])

    def get_average_salary(self):
        return self.salary / len(self.projects)

    def get_project_names(self):
        return [p['name'] for p in self.projects]

    def get_project_duration(self, project_name):
        for p in self.projects:
            if p['name'] == project_name:
                return p['duration']

    def get_project_role(self, project_name):
        for p in self.projects:
            if p['name'] == project_name:
                return p['role']
```

