average_salary = employee.get_average_salary()  # $50000

project_names = employee.get_project_names()  # ['Project A', 'Project B']
```

```rust
use std::{fmt::Write, primes::*,};

fn print_prime_factors(n: i32) {
    if n < 2 {
        return;
    }

    let mut factors = Vec::<usize>();

    for p in primes() {
        while n % p == 0 {
            factors.push(p);
            n /= p;
        }
    }

    if n > 1 {
        factors.push(n);
    }

    write!(&mut println!("Prime factors of {}: ", n), factors);
}
```

**Explanation:**

* The function takes an integer `n` as input.
* It first checks if `n` is less than 2. If so, it returns immediately.
* The function iterates over the `primes()` iterator, which yields prime numbers in ascending order.
* Inside the loop, it checks if `n` is divisible by the current prime number `p` using the modulo operator `%`.
* If `n` is divisible, it repeatedly divides `n` by `p` and stores the prime factor in the `factors` vector.
* Once `n` is no longer divisible by `p`, the loop exits.
* If `n` is greater than 1 after the loop, it means `n` is a prime number, so it is added to the `factors` vector.
* Finally, the function writes the prime factors to the output using the `write!()` method.

**Example Usage:**

```rust
print_prime_factors(-15);
```

**Output:**

```
Prime factors of -15: [-3, 5]
```

**Note:**

* The `primes()` iterator can be used to generate an infinite sequence of prime numbers.
* The modulo operator `%` returns the remainder when `n` is divided by `p`.
* The `write!()` method is used to write data to the output.

```java
import java.util.*;

public class HighestNumber {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter the size of the array: ");
        int size = scanner.nextInt();

        int[] numbers = new int[size];

        System.out.println("Enter the elements of the array: ");
        for (int i = 0; i < size; i++) {
            numbers[i] = scanner.nextInt();
        }

        // Check if the array is empty
        if (numbers.length == 0) {
            System.out.println("The array is empty, cannot find the highest number.");
            return;
        }

        // Find the highest number
        int highest = numbers[0];
        int count = 1;
        for (int i = 1; i < numbers.length; i++) {
            if (numbers[i] > highest) {
                highest = numbers[i];
                count = 1;
            } else if (numbers[i] == highest) {
                count++;
            }
        }

        // Print the highest number and its count
        System.out.println("The highest number is: " + highest);
        System.out.println("The highest number appears " + count + " times in the array.");
    }
}
```

