**Note:**

* The `%` operator returns the remainder when a number is divided by 2.
* If the remainder is 0, the number is even.
* If the remainder is 1, the number is odd.

```python
import math

def isPrime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True


def isEmirp(n):
    if not isPrime(n):
        return False
    return isPrime(int(str(n)[::-1]))


def getEmirpRoot(n):
    if not isPrime(n):
        return -1
    if str(n) == str(n)[::-1]:
        return -1
    for i in range(2, n):
        if isPrime(i) and isPrime(int(str(i)[::-1])):
            return i
    return -1


def main():
    try:
        num = int(input("Enter a number: "))
        if isinstance(num, float) or num <= 0 or num % 1 != 0:
            raise ValueError
        if isEmirp(num):
            print(f"{num} is an emirp number.")
            print(f"Its emirp root is {getEmirpRoot(num)}.")
        else:
            if not isPrime(num):
                print(f"{num} is not prime.")
            elif str(num) == str(num)[::-1]:
                print(f"{num} is a palindrome.")
            else:
                print(f"{num} is not an emirp number.")
    except ValueError:
        print("Invalid input. Please enter a valid integer number.")


if __name__ == "__main__":
    main()
```

**Example Usage:**

```
Enter a number: 13
13 is an emirp number.
Its emirp root is 3.
```

```
Enter a number: 23
23 is not an emirp number.
```

```
Enter a number: 123
123 is not an emirp number. It is not prime.
```

