```java
import java.util.*;

class BankAccount {

    private int accountNumber;
    private double balance;
    private String pin;

    public BankAccount(int accountNumber, double balance, String pin) {
        this.accountNumber = accountNumber;
        this.balance = balance;
        this.pin = pin;
    }

    public void deposit(double amount) {
        balance += amount;
    }

    public boolean withdraw(double amount) {
        if (amount <= balance) {
            balance -= amount;
            return true;
        } else {
            return false;
        }
    }

    public double checkBalance() {
        return balance;
    }

    public boolean validatePin(String enteredPin) {
        return enteredPin.equals(pin);
    }
}

class Bank {

    private List<BankAccount> accounts = new ArrayList<>();

    public BankAccount createAccount(int accountNumber, double initialBalance, String pin) {
        BankAccount newAccount = new BankAccount(accountNumber, initialBalance, pin);
        accounts.add(newAccount);
        return newAccount;
    }

    public BankAccount getAccount(int accountNumber) {
        for (BankAccount account : accounts) {
            if (account.getAccountNumber() == accountNumber) {
                return account;
            }
        }
        return null;
    }
}

public class BankingSystem {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        Bank bank = new Bank();

        System.out.println("Enter 1 to create an account, 2 to login, or 3 to exit: ");
        int choice = scanner.nextInt();

        while (choice != 3) {
            switch (choice) {
                case 1:
                    System.out.println("Enter account number: ");
                    int accountNumber = scanner.nextInt();
                    System.out.println("Enter initial balance: ");
                    double initialBalance = scanner.nextDouble();
                    System.out.println("Enter PIN: ");
                    String pin = scanner.nextLine();
                    BankAccount newAccount = bank.createAccount(accountNumber, initialBalance, pin);
                    System.out.println("Account created successfully.");
                    break;
                case 2:
                    System.out.println("Enter account number: ");
                    int accountNumber = scanner.nextInt();
                    System.out.println("Enter PIN: ");
                    String pin = scanner.nextLine();
                    BankAccount account = bank.getAccount(accountNumber);
                    if (account != null && account.validatePin(pin)) {
                        System.out.println("Balance: $" + account.checkBalance());
                    } else {
                        System.out.println("Invalid account number or PIN.");
                    }
                    break;
            }
            System.out.println("Enter 1 to create an account, 2 to login, or 3 to exit: ");
            choice = scanner.nextInt();
        }
    }
}
```

