from typing import Any


class ICrud:
    def create(self, obj: Any) -> Any:
        pass

    def read(self, id: str) -> Any:
        pass

    def update(self, id: str, obj: Any) -> Any:
        pass

    def delete(self, id: str) -> None:
        pass


class MyCrud:
    def __init__(self):
        self._data = {}

    def create(self, obj: Any) -> Any:
        self._data[obj['id']] = obj
        return obj

    def read(self, id: str) -> Any:
        return self._data.get(id)

    def update(self, id: str, obj: Any) -> Any:
        self._data[id] = obj
        return obj

    def delete(self, id: str) -> None:
        del self._data[id]


# Usage example

crud = MyCrud()

# Create an object
obj = {'id': '1', 'name': 'John Doe'}
created_obj = crud.create(obj)

# Read the created object
read_obj = crud.read('1')
print(read_obj['name'])  # Output: John Doe

# Update the object
updated_obj = {'id': '1', 'name': 'Jane Doe'}
crud.update('1', updated_obj)

# Delete the object
crud.delete('1')

# Check that the object is deleted
assert crud.read('1') is None
```

