import java.util.List;
import java.util.Random;

public class EfficientRandomStringGenerator {

    private static final List<String> CHARS = List.of("a", "b", "c", ..., "z");

    public static String generateRandomString(int length) {
        Random random = new SecureRandom(); // Use a secure random generator
        StringBuilder sb = new StringBuilder(); // Use a StringBuilder for efficiency

        for (int i = 0; i < length; i++) {
            sb.append(CHARS.get(random.nextInt(CHARS.size()))); // Append characters from the list
        }

        return sb.toString();
    }
}
```

