import java.util.*;

public class MaximumSubarrayWithNegativeConstraint {

    public static int maxSubArray(int[] arr) {
        int n = arr.length;
        if (n == 0) {
            return 0;
        }

        int maxSum = arr[0];
        int currSum = arr[0];

        for (int i = 1; i < n; i++) {
            if (currSum < 0) {
                currSum = arr[i];
            } else {
                currSum = currSum + arr[i];
            }

            maxSum = Math.max(maxSum, currSum);
        }

        return maxSum;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5}; // Maximum subarray sum: 15
        int[] arr2 = {1, 2, 3, -4, 5}; // Maximum subarray sum: 5

        System.out.println(maxSubArray(arr)); // Output: 15
