```swift
func utf16ToUtf8(utf16String: String) -> String {
    var utf16Codes = [UInt16](utf16String.utf16)

    var index = 0

    var utf8Codes = [UInt8](repeating: 0, count: 8)

    for value in utf16Codes {
        if value < 0x80 {
            utf8Codes[index] = UInt8(value)
            index += 1
        } else {
            var count = 1
            var high = value >> 8
            var low = value & 0x80

            while high > 0 {
                count += 1
                high >>= 1
            }

            utf8Codes[index] = 0x80 | count
            index += 1

            for _ in 1..<count {
                utf8Codes[index] = (value & 0x7F) << (7 - count)
                index += 1
            }
        }
    }

    return String(bytes: utf8Codes, encoding: .utf8)!
}
```

**Explanation:**

* The function iterates over each character in the UTF-16 string.
* If the character is below 0x80, it is simply copied to the UTF-8 array.
* If the character is above 0x80, it determines the number of code units required to represent the character in UTF-8 encoding.
* It then writes the first code unit, followed by the remaining code units.
* Finally, the function converts the UTF-8 code units to a string and returns the result.

