# This Python code solves a Sudoku puzzle.

# Define the Sudoku board as a 2D list.
sudoku_board = [['_' for _ in range(9)] for _ in range(9)]

# Function to check if a number is valid for a given row and column.
def is_valid(row, col, num):
    for i in range(9):
        if sudoku_board[row][i] == num or sudoku_board[i][col] == num:
            return False
    return True

# Function to find an empty cell.
def find_empty_cell():
    for row in range(9):
        for col in range(9):
            if sudoku_board[row][col] == '_':
                return row, col
    return -1, -1

# Function to solve the Sudoku puzzle.
def solve_sudoku():
    while True:
        row, col = find_empty_cell()
        if row == -1 and col == -1:
            break
        for num in range(1, 10):
            if is_valid(row, col, num):
                sudoku_board[row][col] = num

# Print the solved Sudoku puzzle.
print('Solved Sudoku Puzzle:')
for row in range(9):
    for col in range(9):
        print(sudoku_board[row][col], end=' ')
    print()

```

