function fibonacciSequence(n) {
  if (typeof n !== 'number' || n < 0) {
    return 'Invalid input. Please provide a valid non-negative integer.';
  }

  if (n === 0) {
    return 'Sequence is empty.';
  }

  const sequence = [1];
  let previous = 1;
  let current = 1;

  for (let i = 1; i < n; i++) {
    sequence.push(current);
    previous = current;
    current = sequence[sequence.length - 1] + sequence[sequence.length - 2];
  }

  return { sequence, fibonacci: sequence.slice(-2) };
}

// Example Usage:
