```java
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.firefox.FirefoxDriver;
import org.openqa.selenium.ie.InternetExplorerDriver;

public class CrossBrowserTesting {

    public static void main(String[] args) {

        // List of browser names
        String[] browsers = {"chrome", "firefox", "ie"};

        // Create web driver instances for each browser
        for (String browser : browsers) {
            WebDriver driver;

            switch (browser) {
                case "chrome":
                    driver = new ChromeDriver();
                    break;
                case "firefox":
                    driver = new FirefoxDriver();
                    break;
                case "ie":
                    driver = new InternetExplorerDriver();
                    break;
                default:
                    throw new RuntimeException("Unsupported browser: " + browser);
            }

            // Navigate to the web application URL
            driver.get("https://your-web-application-url.com");

            // Perform tests on the web application
            // ...

            // Close the web driver
            driver.quit();
        }
    }
}
```

