const synonymApi = '//your-api-endpoint';

paragraphElements.forEach(element => {
  element.setAttribute('data-original-content', element.innerHTML); // Store original content for comparison later

  element.innerHTML = element.innerHTML.replace(/(word1|word2|word3)/g, async match => {
