  cancelText?: string;
}

function generateConfirmationDialog({
  header,
  message,
  onConfirm,
  onDismiss,
  confirmColor,
  cancelColor,
  confirmIcon,
  cancelIcon,
  confirmText,
  cancelText,
}: IConfirmationMessageProps) {
