          {cancelText || 'Cancel'}
          {cancelIcon && <span className="lucide-icon">{cancelIcon}</span>}
        </button>
        <button
          className={`button ${confirmColor || 'success'}`}
          onClick={onConfirm}
        >
          {confirmText || 'Confirm'}
