    {"id": 2, "age": 30, "city": "San Francisco", "score": 85},
    {"id": 3, "age": 19, "city": "New York", "score": 90},
]

# Transformation rules
rules = [
    ("add", "score", 5),
    ("subtract", "age", 2),
    ("replace", "city", {"San Francisco": "SF", "New York": "NY"})
]

# Transform the dataset
transformed_data = transform_data(data, rules)

# Print the transformed dataset
print(transformed_data)
```

