```javascript
// Import necessary libraries
const IPFS = require('ipfs')
const { promisify } = require('bluebird')

const DLT = {
  // Initialize IPFS connection
  async init() {
    const ipfs = await IPFS.create({ host: 'localhost', port: 5001 })
    this.ipfs = ipfs
  },

  // Store data on IPFS
  async storeData(data) {
    const storeData = promisify(this.ipfs.add)
    return await storeData(data)
  },

  // Retrieve data from IPFS
  async retrieveData(hash) {
    const getData = promisify(this.ipfs.get)
    const data = await getData(hash)
    return data[0].data
  }
}

module.exports = DLT
