97
```

**Note:**

- The algorithm excludes even numbers with more than two distinct divisors.
- The recursion limit is implicitly defined by the `Math.Sqrt()` function.
- This algorithm is efficient as it uses recursion only when necessary and avoids unnecessary iterations.

```javascript
const express = require('express');
const bodyParser = require('body-parser');

const app = express();

app.use(bodyParser.json());

const posts = [];

app.post('/posts', (req, res) => {
  const newPost = req.body;
  posts.push(newPost);
  res.status(201).json(newPost);
});

app.get('/posts', (req, res) => {
  res.json(posts);
});

app.get('/posts/:id', (req, res) => {
  const post = posts.find(p => p.id === req.params.id);
  post ? res.json(post) : res.status(404).json({ error: 'Post not found' });
});

app.put('/posts/:id', (req, res) => {
  const post = posts.find(p => p.id === req.params.id);
  if (post) {
    post.title = req.body.title;
    post.content = req.body.content;
    res.json(post);
  } else {
    res.status(404).json({ error: 'Post not found' });
  }
});

app.delete('/posts/:id', (req, res) => {
  const index = posts.findIndex(p => p.id === req.params.id);
  index > -1 ? posts.splice(index, 1) : res.status(404).json({ error: 'Post not found' });
  res.json({ message: 'Post deleted successfully' });
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

