const form = document.querySelector('form');

form.addEventListener('submit', (event) => {
  event.preventDefault();

  const number = document.querySelector('#number').value;
  const operator = document.querySelector('#operator').value;

  // Client-side validation
  if (!Number.isInteger(number) || number <= 0) {
    document.querySelector('#numberError').textContent = 'Please enter a positive integer number.';
    return;
  }

  if (operator !== '+' && operator !== '-' && operator !== '*' && operator !== '/') {
    document.querySelector('#operatorError').textContent = 'Please enter a valid operator (+, -, *, /).';
    return;
  }

  // Server-side validation
  // ...

  // Perform the arithmetic operation
  let result;
  switch (operator) {
    case '+':
      result = number + 10;
      break;
    case '-':
      result = number - 10;
      break;
    case '*':
      result = number * 10;
      break;
    case '/':
      result = number / 10;
      break;
  }

  // Display the result
  document.querySelector('#result').textContent = `The result is: ${result}`;
