<!DOCTYPE html>
<html>
<head>
  <title>Form Validation and Local Storage</title>
  <style>
    .error {
      color: red;
    }
  </style>
</head>
<body>

  <form id="form">
    <label for="name">Name:</label>
    <input type="text" id="name" name="name">
    <span class="error" id="nameError"></span><br>

    <label for="email">Email:</label>
    <input type="email" id="email" name="email">
    <span class="error" id="emailError"></span><br>

    <input type="submit" value="Submit">
  </form>

  <div id="result"></div>

  <button id="retrieveData">Retrieve Data</button>
  <button id="deleteData">Delete Data</button>

  <script>
    document.getElementById('form').addEventListener('submit', function(e) {
      e.preventDefault();

      const name = document.getElementById('name').value;
      const email = document.getElementById('email').value;

      validateForm(name, email);
    });

    function validateForm(name, email) {
      let isValid = true;

      if (name === '') {
        document.getElementById('nameError').textContent = 'Name is required';
        isValid = false;
      } else {
        document.getElementById('nameError').textContent = '';
      }

      if (!validateEmail(email)) {
        document.getElementById('emailError').textContent = 'Invalid email address';
        isValid = false;
      } else {
        document.getElementById('emailError').textContent = '';
      }

      if (isValid) {
        storeData(name, email);
        document.getElementById('result').textContent = 'Data saved successfully';
      }
    }

    function validateEmail(email) {
      const regex = /^\S+@\S+\.\S+$/;
      return regex.test(email);
    }

    function storeData(name, email) {
      localStorage.setItem('name', name);
      localStorage.setItem('email', email);
    }

    document.getElementById('retrieveData').addEventListener('click', function() {
      const name = localStorage.getItem('name');
      const email = localStorage.getItem('email');

      document.getElementById('result').textContent = `Name: ${name}, Email: ${email}`;
    });

    document.getElementById('deleteData').addEventListener('click', function() {
      localStorage.removeItem('name');
      localStorage.removeItem('email');

