pragma solidity ^0.8.17;

contract VotingSystem {

    address public owner;
    mapping (address => bool) public voters;
    mapping (uint256 => string) public proposals;
    uint256 public voteCount;

    constructor() {
        owner = msg.sender;
    }

    function addProposal(string memory proposal) public onlyOwner {
        require(proposal.length > 0, "Proposal cannot be empty");
        proposals[voteCount] = proposal;
        voteCount++;
    }

    function vote(uint256 proposalIndex) public {
        require(voters[msg.sender] == false, "Already voted");
        require(proposalIndex >= 0 && proposalIndex < voteCount, "Invalid proposal index");
        voters[msg.sender] = true;
    }

    function getResults() public view returns (string[] memory) {
        string[] memory results = new string[](voteCount);
        for (uint256 i = 0; i < voteCount; i++) {
            results[i] = proposals[i];
        }
        return results;
    }

    function renounceOwnership() public onlyOwner {
        owner = address(0);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can access this function");
        _;
    }
}
```

