```swift
func maxRecursive<T: Comparable>(_ array: [T]) -> (T, Int)? {
    guard array.count > 0 else {
        return nil
    }

    func findMax(_ index: Int, _ currentMax: T, _ currentMaxIndex: Int) -> (T, Int)? {
        if index == array.count {
            return (currentMax, currentMaxIndex)
        }

        if array[index] > currentMax {
            return findMax(index + 1, array[index], index)
        } else {
            return findMax(index + 1, currentMax, currentMaxIndex)
        }
    }

    return findMax(0, array[0], 0)
}
```

**Example Usage:**

```swift
let numbers = [10, 5, 8, 20, 15]

if let (max, index) = maxRecursive(numbers) {
    print("Maximum: \(max), Index: \(index)")
} else {
    print("Array is empty or contains non-comparable values.")
}
```

**Output:**

```
Maximum: 20, Index: 3
```

**Explanation:**

* The `maxRecursive()` function takes an array of integers as input and returns the maximum number and its index.
* It uses a recursive approach to traverse the array.
* The `findMax()` function recursively compares each element with the current maximum and updates the maximum value and index accordingly.
* If the end of the array is reached, the current maximum and its index are returned.
* If the current element is greater than the current maximum, the `findMax()` function is called recursively with the updated maximum and index.
* Otherwise, the `findMax()` function is called recursively with the updated index and the current maximum.

