public void FixDiagnostics(Document document, Diagnostic[] diagnostics, SyntaxEditor editor, CancellationToken cancellationToken)
{
    foreach (var diagnostic in diagnostics)
    {
        switch (diagnostic.Severity)
        {
            case DiagnosticSeverity.Error:
                throw new Exception("Encountered error during fix."); // Handle errors gracefully

            case DiagnosticSeverity.Warning:
                // Handle warnings
                break;

            case DiagnosticSeverity.Info:
                // Handle informational messages
                break;
        }

        // Create a code generator instance based on diagnostic properties
        var generator = editor.Generator.Create(diagnostic.Span, diagnostic.Description);

        // Apply the fixes to the document
        switch (diagnostic.Type)
        {
            case DiagnosticType.Syntax:
                generator.GenerateSyntaxFixes(document);
                break;

            case DiagnosticType.Semantic:
                generator.GenerateSemanticFixes(document);
                break;

            default:
                throw new ArgumentException("Unsupported diagnostic type.");
        }

        // Update the document with the fixes
        document = document.WithGeneratedEdits(generator.Edits);
    }
}
```

**Explanation:**

* **Handling Diagnostics:**
    - The method iterates through the `diagnostics` array and performs different actions based on their `Severity` and `Type`.
* **Code Generation:**
    - For each diagnostic, a `generator` object is created based on the diagnostic's `Span` and `Description`.
    - The `generator`'s `GenerateSyntaxFixes` or `GenerateSemanticFixes` methods are called to apply the necessary fixes to the document.
* **Document Manipulation:**
    - The `document` is updated with the `GeneratedEdits` from the `generator`.
* **Error Handling:**
    - In case of errors during fix application, an exception is thrown.

