```javascript
function parseJson(jsonString) {
  try {
    const jsonObject = JSON.parse(jsonString);

    // Validate date format
    const dateRegex = /^\d{4}-(0?[1-9]|1[0-2])-(0?[1-9]|1[0-2])$/;
    if (!jsonObject.some(value => dateRegex.test(value))) {
      throw new Error('Invalid date format. Date must be in YYYY-MM-DD format.');
    }

    // Handle nested objects and arrays
    const result = {};
    const keys = Object.keys(jsonObject);

    keys.forEach(key => {
      const value = jsonObject[key];

      if (typeof value === 'object' || typeof value === 'array') {
        result[key] = parseJson(JSON.stringify(value));
      } else {
        result[key] = value.replace(/^./, char => char.toUpperCase()).toLowerCase();
      }
    });

    // Check for duplicate keys
    const uniqueKeys = [...new Set(Object.keys(result))];
    if (uniqueKeys.length !== Object.keys(result).length) {
      throw new Error('Duplicate key(s) found.');
    }

    return result;
  } catch (error) {
    console.error('Error during parsing: ', error.message);
    return null;
  }
}
```

**Example Usage:**

