```python
class DatabaseException(Exception):
    pass

class ColumnTypeUnknown(Exception):
    pass

class NotAllowed(Exception):
    pass


class Database:

    def __init__(self):
        self.__tables = {}

    def create_table(self, table_name, columns):
        if table_name in self.__tables:
            raise DatabaseException("Table already exists")

        for column, data_type in columns.items():
            if data_type not in ['int', 'str', 'float']:
                raise ColumnTypeUnknown(f"Unknown column type: {data_type}")

        self.__tables[table_name] = {'columns': columns, 'records': []}

    def insert_record(self, table_name, record):
        if table_name not in self.__tables:
            raise DatabaseException("Table does not exist")

        for column, value in record.items():
            if column not in self.__tables[table_name]['columns']:
                raise DatabaseException(f"Column '{column}' not found in table")

        self.__tables[table_name]['records'].append({column: value for column in record})

    def query(self, table_name, condition):
        if table_name not in self.__tables:
            raise DatabaseException("Table does not exist")

        filtered_records = []
        for record in self.__tables[table_name]['records']:
            for column, value in record.items():
                if column + ' ' + value + ' ' in condition:
                    filtered_records.append(record)
                    break

        return filtered_records
```

**Example Usage:**

```python
# Create a database object
db = Database()

# Create a table called "users"
db.create_table('users', {
    'name': 'str',
    'email': 'str',
    'age': 'int'
})

# Insert some records into the table
db.insert_record('users', {'name': 'John Doe', 'email': 'john.doe@example.com', 'age': 30})
db.insert_record('users', {'name': 'Jane Doe', 'email': 'jane.doe@example.com', 'age': 25})

# Query the users table for those with an age greater than 25
results = db.query('users', 'age > 25')
```

