Additionally, you should ensure that the function throws an error if the input array contains any non-numeric values.

Example input: [10, "15", 7, 12, 17, 20]

Example output: [7, 17]

Erroneous code reference:
```
function filterPrimes(arr) {
  if (!Array.isArray(arr)) {
    throw new Error('Input must be an array');
  }

  return arr.filter(num => {
    if (typeof num !== 'number') {
      throw new Error('Input array can only contain numeric values');
    }

    if (num < 2) {
      return false;
    }

    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) {
        return false;
      }
    }

    return true;
  });
}
