```python
import requests
from bs4 import BeautifulSoup

def extract_meta_tags(html):
    soup = BeautifulSoup(html, 'html.parser')
    title = None
    description = None
    keywords = None

    # Find title meta tag
    for meta in soup.find_all('meta'):
        if meta.get('name') == 'title':
            title = meta.get('content')
            break

    # Find description meta tag
    for meta in soup.find_all('meta'):
        if meta.get('name') == 'description':
            description = meta.get('content')
            break

    # Find keywords meta tag
    for meta in soup.find_all('meta'):
        if meta.get('name') == 'keywords' or meta.get('name') == 'robots' and meta.get('content').startswith('keywords='):
            keywords = meta.get('content').split(',')

    return {'title': title, 'description': description, 'keywords': keywords}


def main():
    try:
        url = input("Enter the URL: ")
        response = requests.get(url)
        html = response.content

        meta_tags = extract_meta_tags(html)

        print("Title:", meta_tags['title'])
        print("Description:", meta_tags['description'])
        print("Keywords:", ' '.join(meta_tags['keywords']))

    except requests.exceptions.RequestException as e:
        print("Error: Connection failed. Please check the URL or network connection.")

    except Exception as e:
        print("Error: Something went wrong while extracting meta tags.")


if __name__ == "__main__":
    main()
```

