class VolumeAdvanced:

    def __init__(self, shape_type, dimensions):
        self.shape_type = shape_type
        self.dimensions = dimensions

    def calculate_volume(self):
        if self.shape_type == "sphere":
            return (4 / 3) * math.pi * (self.dimensions[0]**3)
        elif self.shape_type == "cylinder":
            return math.pi * (self.dimensions[0]**2) * self.dimensions[1]
        # ... Implement other shapes ...

    def compare_volumes(self, other):
        if isinstance(other, VolumeAdvanced):
            if self.calculate_volume() > other.calculate_volume():
                return f"{self.shape_type} has a larger volume by {((self.calculate_volume() - other.calculate_volume()) / other.calculate_volume()) * 100:.2f}%"
            else:
                return f"{other.shape_type} has a larger volume by {((other.calculate_volume() - self.calculate_volume()) / self.calculate_volume()) * 100:.2f}%"
        else:
            raise ValueError("Cannot compare volumes of different shapes.")

    def subtract_volume(self, other):
        if isinstance(other, VolumeAdvanced):
            return self.calculate_volume() - other.calculate_volume()
        else:
            raise ValueError("Cannot subtract volumes of different shapes.")


def test_volume_advanced():
    sphere = VolumeAdvanced("sphere", [2])
    cylinder = VolumeAdvanced("cylinder", [2, 3])
    cone = VolumeAdvanced("cone", [2, 4])

    assert sphere.calculate_volume() == (4 / 3) * math.pi * 2**3
    assert cylinder.calculate_volume() == math.pi * 2**2 * 3
    assert cone.calculate_volume() == (1 / 3) * math.pi * 2**2 * 4

    assert sphere.compare_volumes(cylinder) == "cylinder has a larger volume by 50.37%"
    assert sphere.subtract_volume(cylinder) == -((4 / 3) * math.pi * 2**3 - math.pi * 2**2 * 3)
```

