use criterion::{black_box, Criterion};
use serde_json::{from_str, Value};
use stats_alloc::{MemTracker, Tracking};

fn json_serialization_benchmark(c: &mut Criterion) {
    let sample_json = r#"
    {
        "name": "John Doe",
        "email": "john.doe@example.com",
        "age": 30
    }"#;

    c.bench("JsonSerialization", black_box(|| {
        let mut tracker = MemTracker::new();

        // Track memory allocation before serialization
        tracker.track();

        // Deserialize the JSON string
        let json: Value = from_str(sample_json).unwrap();

        // Serialize the JSON value
        let serialized = serde_json::to_string(&json).unwrap();

        // Track memory allocation after serialization
        let allocated = tracker.allocated();

        // Assert that memory allocation is within threshold
        assert!(allocated <= 1024); // Adjust threshold as needed

        // Return the serialized JSON string
        serialized
    }))
}
```

