    { name: 'John', age: 17 },
    { name: 'Jane', age: 20 },
    { name: 'Mark', age: 19 },
];

const keyword = 'jane';

const result = searchObjects(objects, keyword);

console.log(result); // true
```

**Note:**

* The function handles special characters in the keyword.
* The array size is limited to 100 objects and the keyword length is capped at 10 characters for performance optimization.

