    'amount': {
        # ...
    },
    'payment_way': {
        # ...
    },
}

# Define the input data
input_data = {
    'amount': '123.45',
}

# Validate and manipulate the data
result = validate_and_manipulate_data(data_structure, input_data)
print(result)
```

