    const resultsElement = document.getElementById('results');

    fetch('getGrades.php')
      .then(res => res.json())
      .then(data => {
        subjectElement.innerHTML = `<option value='${data.subjects[0]}'>${data.subjects[0]}</option>`;
        for (let i = 1; i < data.subjects.length; i++) {
          subjectElement.innerHTML += `<option value='${data.subjects[i]}'>${data.subjects[i]}</option>`;
        }
      });

