        this.replicationMasterUrl = masterUrl;
        this.replicationSlaveUrl = slaveUrl;
    }

    public void automateReplication() {
        final QuartzScheduler scheduler = new QuartzScheduler();

        // Schedule daily replication task
        scheduler.scheduleJob(new Job() {
            @Override
