                // Get database and collection names
                String databaseName = "myDatabase";
                String collectionName = "myCollection";

                // Ensure slave is not primary
                if (isPrimary(replicationSlaveUrl)) {
                    return;
                }

                // Replicate data from master to slave
                replicateData(databaseName, collectionName);
            }
        }, "ReplicationJob", new CronSchedule("0 0 1 * *"));
    }

    private void replicateData(String databaseName, String collectionName) {
        // Get collection objects
        MongoCollection<Document> masterCollection = mongoClient.getDatabase(databaseName).getCollection(collectionName);
        MongoCollection<Document> slaveCollection = new MongoClient(replicationSlaveUrl).getDatabase(databaseName).getCollection(collectionName);

        // Get documents from master collection
        List<Document> documents = masterCollection.find().into(new ArrayList<>());

        // Insert documents into slave collection
        slaveCollection.insertMany(documents);
    }

    private boolean isPrimary(String mongoUrl) {
