```python
import requests
import threading
import time

def access_rates(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error fetching data from {url}")
        return None

def compare_rates(rates1, rates2):
    for key, value in rates1.items():
        if key not in rates2:
            print(f"{key} not found in the older data.")
            continue
        if rates1[key] > rates2[key]:
            print(f"{key} rate has increased from {rates2[key]} to {rates1[key]}.")
        elif rates1[key] < rates2[key]:
            print(f"{key} rate has decreased from {rates2[key]} to {rates1[key]}.")

def main():
    urls = ["https://api.exchangeratesapi.io/latest", "https://api.exchangeratesapi.io/2020-01-01"]
    start_time = time.time()
    while time.time() - start_time < 300:
        for url in urls:
            rates = access_rates(url)
            if rates is not None:
                if url == urls[0]:
                    latest_rates = rates
                else:
                    compare_rates(latest_rates, rates)
        time.sleep(30)

if __name__ == "__main__":
    main()
```

**Explanation:**

**1. Accessing Data from Web Addresses:**

- The `access_rates` function fetches data from the specified web address using the `requests` library.
- It handles connection issues and data unavailability gracefully.

**2. Threading:**

- The code uses threading to fetch data from both URLs simultaneously, improving efficiency.

**3. Time Delay:**

