// Complex Sentence Structure Grammar

// Sentence production rule
sentence : noun phrase verb phrase { $$ = $1 $2; }

// Noun phrase production rule
noun phrase : noun { $$ = $1; }
noun phrase : noun phrase preposition noun { $$ = $1 $2 $3; }

// Verb phrase production rule
verb phrase : verb { $$ = $1; }
verb phrase : verb noun phrase { $$ = $1 $2; }

// Noun production rule
noun : "John" {}
noun : "Mary" {}

// Preposition production rule
preposition : "to" {}
preposition : "from" {}

// Verb production rule
verb : "likes" {}
verb : "hates" {}

// Test sentence
sentence : "John likes Mary to the store." { $$ = "John likes Mary to the store."; }

// CKY Parser Code

void yyerror(const char *s) {
  fprintf(stderr, "Parse error: %s\n", s);
  exit(1);
}

void yyparse() {
  yyparse();
}

int main() {
  yyparse();
  return 0;
}
```

