import random
import string

def generate_password():
    uppercase = list(string.ascii_uppercase)
    lowercase = list(string.ascii_lowercase)
    digits = list(range(0, 10))
    special_chars = list([",", "!"]

    password = []

    for i in range(16):
        if len(password) < 2 or password[-1] in uppercase and password[-2] in uppercase:
            password.append(random.choice(lowercase))
        elif len(password) < 2 or password[-1] in lowercase and password[-2] in lowercase:
            password.append(random.choice(uppercase))
        elif len(password) < 2 or password[-1] in digits and password[-2] in digits:
            password.append(random.choice(digits))
        else:
            password.append(random.choice(special_chars))

    return ''.join(password)

password = generate_password()
print(password)
```

```python
import json

def extract_sorted_key_value_pairs(nested_json):
    key_value_pairs = {}

    def traverse(data):
        if isinstance(data, dict):
            for key, value in data.items():
                traverse(value)
                key_value_pairs[key] = value
        elif isinstance(data, list):
            for item in data:
                traverse(item)
        else:
            key_value_pairs[data['key']] = data['value']

    traverse(nested_json)

    sorted_pairs = sorted(key_value_pairs.items(), key=lambda x: x[1], reverse=True)

    return sorted_pairs
```

**Example Usage:**

