    def __init__(self, name, files=None):
        self.name = name
        self.files = files or []

    def add_file(self, file):
        self.files.append(file)

    def add_directory(self, directory):
        self.files.append(directory)

    def navigate(self, directory):
        self.files = [f for f in self.files if f.name == directory]

    def display_contents(self):
        print(f"{self.name}:")
        for file in self.files:
            if isinstance(file, File):
                print(f" - {file.name}")
            elif isinstance(file, Directory):
                print(f" - {file.name}")


class FileSystem:
    def __init__(self):
        self.root = Directory("root")

    def create_file(self, name, content):
        self.root.add_file(File(name, content))

    def create_directory(self, name):
        self.root.add_directory(Directory(name))

    def navigate_to_directory(self, name):
        self.root.navigate(name)

    def display_file_system(self):
        self.root.display_contents()


if __name__ == "__main__":
    fs = FileSystem()

    fs.create_directory("root")
    fs.navigate_to_directory("root")
    fs.create_file("file1.txt", "This is the content of file1")
    fs.create_directory("subdir1")
    fs.navigate_to_directory("subdir1")
    fs.create_file("file2.txt", "Content of file2")
    fs.navigate_to_directory("..")

    fs.display_file_system()
```

