```python
def partition(lo, hi, cmp_func):
    pivot = l[hi]
    i = lo - 1

    for j in range(lo, hi):
        if cmp_func(l[j], pivot) <= 0:
            i += 1
            l[i], l[j] = l[j], l[i]

    l[i + 1], l[hi] = l[hi], l[i + 1]
    return i + 1


def select_nth(l, n, cmp_func, lo=None, hi=None):
    if lo is None: lo = 0
    if hi is None: hi = len(l) - 1

    pivot_index = partition(lo, hi, cmp_func)

    if pivot_index == n:
        return l[n]
    elif pivot_index < n:
        return select_nth(l, n, cmp_func, lo, pivot_index - 1)
    else:
        return (select_nth(l, n // 2 - 1, cmp_func) + select_nth(l, n // 2, cmp_func)) / 2.0


def median(l, cmp_func):
    if not l: return None
    n = len(l)
    if n % 2 == 1:
        return select_nth(l, n // 2, cmp_func)
    else:
        return (select_nth(l, n // 2 - 1, cmp_func) + select_nth(l, n // 2, cmp_func)) / 2.0
```

**Changes Made:**

* Fixed spelling errors: "p@rtition" -> "partition", "qivot" -> "pivot", "re+urn" -> "return", "ze1€<t_n7n" -> "select_nth"
