    if (count < 1 || count > 100) {
        printf("Error: The count must be between 1 and 100.\n");
        return 1;
    }

    // Print the text to the terminal
    for (int i = 0; i < count; i++) {
        printf("Hello World\n");
    }

    return 0;
}
