import os

def handle_requests(request_file, key_file):
    # Read and parse keywords from key file
    keywords = {}
    with open(key_file, 'r') as f:
        for line in f:
            keyword, action = line.strip().split(':')
            keywords[keyword] = action

    # Read requests from request file
    with open(request_file, 'r') as f:
        for request in f:
            request = request.strip()

            # Check if keyword is in key file and execute action
            if request in keywords:
                action = keywords[request]
                print(f"Executing action: {action}")
            else:
                print(f"Action not found for keyword: {request}")
```

