    document.getElementById('changeColor').addEventListener('click', () => {
      const newFont = fonts[Math.floor(Math.random() * fonts.length)];
      const newColor = colors[Math.floor(Math.random() * colors.length)];

      // Ensure that the options are not repeated until all options have been used at least once
      while (usedFonts.includes(newFont) || usedColors.includes(newColor)) {
        newFont = fonts[Math.floor(Math.random() * fonts.length)];
        newColor = colors[Math.floor(Math.random() * colors.length)];
      }

      document.getElementById('message').style.fontFamily = newFont;
      document.getElementById('message').style.color = newColor;

      usedFonts.push(newFont);
      usedColors.push(newColor);

      // Reset the lists once all options have been used
      if (usedFonts.length === fonts.length && usedColors.length === colors.length) {
        usedFonts = [];
        usedColors = [];
      }
    });
  </script>

