        if (is_prime($i)) {
          echo '<tr>';
          echo '<td>' . $i . '</td>';
          echo '<td>';
          $factors = getFactors($i);
          foreach ($factors as $factor) {
            echo $factor . ' ';
          }
          echo '</td>';
          echo '</tr>';
        }
      }

      function is_prime($number) {
        if ($number < 2) {
          return false;
        }
        for ($i = 2; $i <= sqrt($number); $i++) {
          if ($number % $i === 0) {
            return false;
          }
        }
        return true;
      }

      function getFactors($number) {
        $factors = array();
        for ($i = 2; $i <= sqrt($number); $i++) {
          while ($number % $i === 0) {
            $factors[] = $i;
            $number /= $i;
          }
        }
        if ($number > 1) {
          $factors[] = $number;
        }
        return $factors;
      }
      ?>
    </tbody>
  </table>

