import functools as ft
import logging

class SoundPlayer:
    def __init__(self, trap_errors=False):
        self.trap_errors = trap_errors
        self.log = logging.getLogger('SoundPlayer')
        self._cached_sounds = {}

    def play(self, name):
        sound_func = self._create_partial_functions()['play']
        sound_func(name)

    def play_sync(self, name):
        sound_func = self._create_partial_functions()['play_sync']
        sound_func(name)

    def cache(self, name):
        sound_func = self._create_partial_functions()['cache']
        self._cached_sounds[name] = sound_func

    def _handle_error(self, name, err):
        if not self.trap_errors:
            self.log.exception('Failed to play sound sample %r: %s', name, err)

    def _create_partial_functions(self):
        def snd(name):
            if name not in self._cached_sounds:
                self._cached_sounds[name] = functools.partial(self._play_sound, name)
            return self._cached_sounds[name]()

        def _play_sound(name):
            # Placeholder for actual sound playback function
            print(f'Playing sound sample: {name}')

        res = dict((k, ft.partial(snd, k)) for k in 'play play_sync cache'.split())
        return res

# Usage
