```python
# This function checks if a number is prime.
def isPrime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True


# This function returns the prime factorization of a number.
def primeFactors(n):
    factors = []
    while n > 1:
        for p in range(2, int(n**0.5) + 1):
            if isPrime(p) and n % p == 0:
                factors.append(p)
                n //= p
                break
    return factors


# This function returns the greatest common divisor of two numbers.
def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)


# This function returns the least common multiple of two numbers.
def lcm(a, b):
    return (a * b) // gcd(a, b)


# This function finds the greatest common divisor of all numbers in a list.
def gcdList(list):
    if not list:
        return 1
    return gcd(list[0], gcdList(list[1:]))


# This function finds the least common multiple of all numbers in a list.
def lcmList(list):
    if not list:
        return 1
    return lcm(list[0], lcmList(list[1:]))
```

