func createTransferRequestWithSignature(userUUID: String, sourceUserUUID: String, destinationUserUUID: String, nineumUniqueIds: [String], price: Int, currencyName: String, ordinal: Int, timestamp: String) -> TransferRequestWithSignature {
    let transferRequest = TransferRequestWithSignature(userUUID: userUUID, sourceUserUUID: sourceUserUUID, destinationUserUUID: destinationUserUUID, nineumUniqueIds: nineumUniqueIds, price: price, currencyName: currencyName, ordinal: ordinal, timestamp: timestamp)

