```javascript
function styleHtml(htmlCode) {
  const regex = /<(\w+)[^>]*>/g;
  let modifiedHtml = htmlCode;

  // Remove existing inline styles from paragraph, div, and span tags
  modifiedHtml = modifiedHtml.replace(regex, (match) => {
    const tag = match.slice(1, -1);
    return `<${tag} style="${match.slice(2, -1).replace(/style="|"/g, '')}"></${tag}>`;
  });

  // Add padding to paragraph tags
  modifiedHtml = modifiedHtml.replace(/<p>/g, '<p style="padding: 10px;">');

  // Add margin to div tags
  modifiedHtml = modifiedHtml.replace(/<div>/g, '<div style="margin: 5px;">');

  // Add background color to span tags
  modifiedHtml = modifiedHtml.replace(/<span>/g, '<span style="background-color: #f1f1f1;">');

  return modifiedHtml;
}
```

