import java.lang.annotation.*;
import java.util.Set;

import javax.annotation.processing.*;
import javax.lang.model.*;

@SupportedAnnotation(Audit.class)
public class AuditAnnotationProcessor implements AnnotationProcessor {

    @Override
    public void process(Set<? extends Annotation> annotations, TypeElement element) {
        element.getMethods().forEach(method -> {
            if (method.getAnnotation(UpdateTimestamp.class) != null) {
                method.getParameters().stream()
                        .filter(p -> p.getType().equals(ZonedDateTime.class))
                        .findFirst()
                        .ifPresent(p -> {
                            p.addAnnotation(new Column(name = "audit_updated_on"));
                            p.addAnnotation(new UpdateTimestamp());
                        });
            }
        });
    }
}
```

