[
  { level: 1, text: 'Introduction', line: 1 },
  { level: 2, text: 'Section 1', line: 4 },
  { level: 3, text: 'Subsection 1.1', line: 7 },
  { level: 2, text: 'Section 2', line: 10 }
]
```

