class KLRegularizer:
    def __init__(self, coeff=1.0, p=None):
        self.coeff = coeff
        self.p = p

    def expr(self, model, X, **kwargs):
        p_hat = model.encode(X, **kwargs)
        if self.p is None:
            p = model.get_true_distribution(X)
        else:
            p = self.p

        kl = p * torch.log(p / p_hat) + (1 - p) * torch.log((1 - p) / (1 - p_hat))
        return self.coeff * torch.mean(kl)
```

