```java
public class AcademicScorecardManager {

    private Map<String, List<Integer>> scorecards;

    public AcademicScorecardManager() {
        this.scorecards = new HashMap<>();
    }

    public void addGradingEntry(String studentName, int grade) {
        List<Integer> scores = scorecards.getOrDefault(studentName, new ArrayList<>());
        scores.add(grade);
        scorecards.put(studentName, scores);
    }

    public int calculateMeanScore(String studentName) {
        List<Integer> scores = scorecards.getOrDefault(studentName, new ArrayList<>());
        int sum = 0;
        for (int score : scores) {
            sum += score;
        }
        return sum / scores.size();
    }
}
```

