public class MyApplication extends Application implements Thread.UncaughtExceptionHandler {

    @Override
    public void onCreate() {
        super.onCreate();
        Thread.setDefaultUncaughtExceptionHandler(this);
    }

    @Override
    public void uncaughtException(Thread thread, Throwable ex) {
        Log.e("Uncaught Exception:", "Unexpected error occurred", ex);

        // Display a custom error message to the user
        final String errorMessage = "An unexpected error occurred. Please try again later.";
        Toast.makeText(this, errorMessage, Toast.LENGTH_LONG).show();

        // Prevent the default uncaught exception handler from running
        ex.printStackTrace();
    }
}
