```cpp
#include <librealsense2/rs.hpp>

// Function to process depth data
std::pair<int, int> processDepthData(const rs2::depth_intrinsics& depth_intrin,
                                     const rs2::video_stream_profile& other_intrin,
                                     const rs2::depth_frame& depth_frame,
                                     const rs2::video_stream_profile& other_profile,
                                     const rs2::align& aligner,
                                     const rs2::context& ctx) {
    // Obtain depth pixel coordinates
    const int depth_pixel_x = 100;  // Example depth_pixel_x coordinate
    const int depth_pixel_y = 150;  // Example depth_pixel_y coordinate

    // Deproject depth pixel to obtain 3D point
    rs2::depth_frame depth = aligner.process(depth_frame);
    float depth_pixel[2] = {static_cast<float>(depth_pixel_x), static_cast<float>(depth_pixel_y)};
    float depth_point[3];
    rs2_deproject_pixel_to_point(depth_point, &depth_intrin, depth_pixel, depth.get_distance(depth_pixel_x, depth_pixel_y));

    // Transform 3D point to other coordinate system
    float other_point[3];
    rs2_transform_point_to_point(other_point, &depth_to_other, depth_point);

    // Project 3D point onto 2D image plane in other coordinate system
    float other_pixel[2];
    rs2_project_point_to_pixel(other_pixel, &other_intrin, other_point);

    // Round the projected pixel coordinates to nearest integers
    const int other_x = static_cast<int>(other_pixel[0] + 0.5f);
    const int other_y = static_cast<int>(other_pixel[1] + 0.5f);

    return std::make_pair(other_x, other_y);
}
