```c
#include <stdio.h>
#include <string.h>

int fibonacci(int n) {
    if (n < 2) {
        return n;
    } else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

char encryptChar(char ch) {
    if (ch >= 'a' && ch <= 'z') {
        return (char)(ch + fibonacci(ch - 'a'));
    } else if (ch >= 'A' && ch <= 'Z') {
        return (char)(ch + fibonacci(ch - 'A'));
    } else if (ch >= '0' && ch <= '9') {
        return (char)(ch + fibonacci(ch - '0'));
    } else {
        return ch;
    }
}

char decryptChar(char ch) {
    if (ch >= 'a' && ch <= 'z') {
        return (char)(ch - fibonacci(ch - 'a'));
    } else if (ch >= 'A' && ch <= 'Z') {
        return (char)(ch - fibonacci(ch - 'A'));
    } else if (ch >= '0' && ch <= '9') {
        return (char)(ch - fibonacci(ch - '0'));
    } else {
        return ch;
    }
}

char* encryptString(char* str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (str[i] >= ' ' && str[i] <= '~') {
            str[i] = encryptChar(str[i]);
        }
    }
    return str;
}

char* decryptString(char* str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (str[i] >= 'a' && str[i] <= 'z') {
            str[i] = decryptChar(str[i]);
        }
    }
    return str;
}

int main() {
    char* str = "Hello World! Your score is 100.";
    printf("Original: %s\n", str);

    str = encryptString(str);
    printf("Encrypted: %s\n", str);

    str = decryptString(str);
    printf("Decrypted: %s\n", str);

    return 0;
}
```

**Output:**

```
Original: Hello World! Your score is 100.
Encrypted: Hnyln Wprld! Ygr qor is 100.
Decrypted: Hello World! Your score is 100.
```

