```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define BUFFER_SIZE 10
#define PRODUCER_COUNT 2
#define CONSUMER_COUNT 3

struct Buffer {
    int items[BUFFER_SIZE];
    int head;
    int tail;
    int count;
};

struct Producer {
    struct Buffer *buffer;
    int capacity;
};

struct Consumer {
    struct Buffer *buffer;
    int rate;
};

void *producer(void *arg) {
    struct Producer *producer = (struct Producer *)arg;
    for (int i = 0; i < producer->capacity; i++) {
        while (producer->buffer->count == BUFFER_SIZE) {
            pthread_cond_wait(&producer->buffer->consumer_cond, &producer->buffer->mutex);
        }
        producer->buffer->items[producer->buffer->head] = i;
        producer->buffer->head = (producer->buffer->head + 1) % BUFFER_SIZE;
        producer->buffer->count++;
        pthread_cond_signal(&producer->buffer->consumer_cond);
    }
    pthread_exit(NULL);
}

void *consumer(void *arg) {
    struct Consumer *consumer = (struct Consumer *)arg;
    while (1) {
        while (consumer->buffer->count == 0) {
            pthread_cond_wait(&consumer->buffer->producer_cond, &consumer->buffer->mutex);
        }
        int item = consumer->buffer->items[consumer->buffer->tail];
        consumer->buffer->tail = (consumer->buffer->tail + 1) % BUFFER_SIZE;
        consumer->buffer->count--;
        pthread_cond_signal(&consumer->buffer->producer_cond);
        // Simulate consumption rate
        sleep(1);
    }
    pthread_exit(NULL);
}

int main() {
    struct Buffer buffer;
    buffer.items = malloc(sizeof(int) * BUFFER_SIZE);
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    pthread_cond_init(&buffer.producer_cond);
    pthread_cond_init(&buffer.consumer_cond);
    pthread_mutex_init(&buffer.mutex);

    struct Producer producers[PRODUCER_COUNT];
    for (int i = 0; i < PRODUCER_COUNT; i++) {
        producers[i].buffer = &buffer;
        producers[i].capacity = BUFFER_SIZE;
    }

    struct Consumer consumers[CONSUMER_COUNT];
    for (int i = 0; i < CONSUMER_COUNT; i++) {
        consumers[i].buffer = &buffer;
        consumers[i].rate = 1;
    }

    pthread_t producer_threads[PRODUCER_COUNT];
    pthread_t consumer_threads[CONSUMER_COUNT];

    for (int i = 0; i < PRODUCER_COUNT; i++) {
        pthread_create(&producer_threads[i], NULL, producer, &producers[i]);
    }

    for (int i = 0; i < CONSUMER_COUNT; i++) {
        pthread_create(&consumer_threads[i], NULL, consumer, &consumers[i]);
    }

    for (int i = 0; i < PRODUCER_COUNT; i++) {
        pthread_join(producer_threads[i], NULL);
    }

    for (int i = 0; i < CONSUMER_COUNT; i++) {
        pthread_join(consumer_threads[i], NULL);
    }

    printf("Total items produced: %d\n", buffer.count);
    printf("Total items consumed: %d\n", buffer.count);

    return 0;
}
```

**1. Handling Case of Total Items Produced Less Than Consumed:**

