use aws_smithy_json::{Deserialize, Deserializer};

use crate::error::global_table_not_found_exception::Builder;

fn deserialize_global_table_not_found_exception(
    value: &[u8],
    builder: Builder,
) -> Result<Builder, aws_smithy_json::deserialize::Error> {
    let result = Deserializer::from_slice(value)
        .deserialize_struct("GlobalTableNotFoundException", builder)?;

    match result {
        Ok(builder) => {
            Ok(builder)
