}
```

```python
import json


def validate_and_format_json(data):
    schema = {
        "name": {"required": True},
        "age": {"required": True, "type": "integer", "minimum": 0},
        "address": {"required": True, "type": "object", "properties": {
            "street": {"required": True, "type": "string"},
            "city": {"required": True, "type": "string"},
            "state": {"required": True, "type": "string"},
            "country": {"required": True, "type": "string"}
        }},
        "contact": {"required": True, "type": "object", "properties": {
            "email": {"required": True, "type": "string"},
            "phone": {"required": True, "type": "string"}
        }},
        "hobbies": {"required": True, "type": "array"},
        "languages": {"required": True, "type": "object", "properties": {
            "english": {"required": True, "type": "boolean"},
            "spanish": {"required": False, "type": "boolean"},
            "french": {"required": False, "type": "boolean"}
        }}
    }

    try:
        json.dumps(data, indent=4)
        if not all(key in data for key in schema):
            raise ValueError("Missing required fields.")

        for key, value in schema.items():
            if isinstance(value, dict):
                for inner_key, inner_value in value.items():
                    if isinstance(inner_value, str):
                        if not isinstance(data[key][inner_key], inner_value):
                            raise ValueError(f"{key} field invalid type.")
                    elif isinstance(inner_value, bool):
                        if not isinstance(data[key][inner_key], bool):
                            raise ValueError(f"{key} field invalid type.")
            elif isinstance(value, list):
                if not isinstance(data[key], list):
                    raise ValueError(f"{key} field invalid type.")

        return json.dumps(data, indent=4)

    except ValueError as e:
        raise ValueError(f"Validation error: {e}") from e
```

**Example Usage:**

```python
# Valid JSON data
data = {
    "name": "John",
    "age": 20,
    # ...
}

formatted_json = validate_and_format_json(data)

# Output:
"""
{
    "name": "John",
    "age": 20,
    // ...
}
"""

# Invalid JSON data (missing age field)
data = {"name": "John", "address": {...}}

try:
    formatted_json = validate_and_format_json(data)
except ValueError as e:
    print(e)  # Output: Validation error: Missing required field.
```

```javascript
function nestedSearch(arr, param) {
  const insensitiveParam = param.toLowerCase();

  return arr.filter(obj => {
    const keys = Object.keys(obj);

    for (let key of keys) {
      if (obj[key].toString().toLowerCase().includes(insensitiveParam)) {
        return true;
      }

      if (typeof obj[key] === 'object') {
        const nestedResults = nestedSearch(obj[key], insensitiveParam);
        if (nestedResults.length > 0) {
          return true;
        }
      }
    }

    return false;
  });
}
```

**Example Usage:**

