```python
import requests

def get_user_details(api_key='12345', user_agent='Application v1.1.1'):
    url = 'https://api.domain.com/api/v4/user'

    # Define headers with API key and User-Agent
    headers = {
        'Authorization': f'Bearer {api_key}',
        'User-Agent': user_agent,
    }

    # Set rate limit parameters
    rate_limit_interval = 20
    rate_limit_count = 4

    # Function to handle rate limiting
    def rate_limited(func):
        def wrapper(*args, **kwargs):
            last_request = None
            while True:
                try:
                    response = func(*args, **kwargs)
                    return response
                except requests.exceptions.TooManyRequests:
                    if last_request is not None:
                        time_elapsed = (datetime.datetime.now() - last_request).total_seconds()
                        if time_elapsed >= rate_limit_interval:
                            return func(*args, **kwargs)
                    else:
                        time.sleep(rate_limit_interval / rate_limit_count)
                        continue
                finally:
                    last_request = datetime.datetime.now()
        return wrapper

    # Call the rate-limited function to fetch user details
    @rate_limited
    def fetch_user_details():
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.json()
        else:
            raise RuntimeError(f'Error fetching user details: {response.text}')

    # Call the fetch_user_details function to retrieve user details
    try:
        user_details = fetch_user_details()
    except Exception as e:
        print(f'Error: {e}')
    else:
        print(f'User details:\n{user_details}')
```

```csharp
public static bool IsSorted(int[,] array)
{
    // Check row-wise sorting
    for (int i = 0; i < array.GetLength(0); i++)
    {
        for (int j = 1; j < array.GetLength(1); j++)
        {
            if (array[i, j] < array[i, j - 1])
            {
                return false;
            }
        }
    }

    // Check column-wise sorting
    for (int j = 0; j < array.GetLength(1); j++)
    {
        for (int i = 1; i < array.GetLength(0); i++)
        {
            if (array[i, j] < array[i - 1, j])
            {
                return false;
            }
        }
    }

    return true;
}
```

**Explanation:**

* **Row-wise sorting:**
    * Iterates over rows and compares adjacent elements.
    * If any element is less than the previous one, it indicates row-wise sorting is not maintained and returns `false`.


* **Column-wise sorting:**
    * Iterates over columns and compares adjacent elements.
    * If any element is less than the previous one, it indicates column-wise sorting is not maintained and returns `false`.


* **Return value:**
    * If both row-wise and column-wise sorting are confirmed, the method returns `true`.

**Example:**

```csharp
int[,] sortedArray = {
    { 1, 2, 3 },
    { 4, 5, 6 },
    { 7, 8, 9 }
};

bool isSorted = IsSorted(sortedArray); // isSorted = true
```

**Note:**

* This algorithm assumes that the array is not null and has at least one row and one column.
* The comparison operators (`<`) are used to check for ascending order.
* The algorithm is efficient, performing O(n) time complexity.

