```javascript
function countVowels(str) {
    str = str.toLowerCase().replace(/[^a-z0-9]/g, ''); // remove non-alphabetic characters and spaces
    const vowels = {};
    for (let char of str) {
        if (char !== 'a' && char !== 'e' && vowels[char] !== undefined) {
            vowels[char]++;
        }
    }
    return vowels;
}

function findMostCommonVowel(vowels) {
    let maxCount = 0;
    let mostCommonVowel = '';
    for (let vowel in vowels) {
        if (vowels[vowel] > maxCount) {
            maxCount = vowels[vowel];
            mostCommonVowel = vowel;
        }
    }
    return mostCommonVowel;
}

// Example Usage:
const str = 'This sentence has a lot of vowels like o, i, and u!';
const vowels = countVowels(str);
const mostCommonVowel = findMostCommonVowel(vowels);

console.log('Vowels:', vowels);
console.log('Most Common Vowel:', mostCommonVowel);
```

