class OnlineStoreInventory:
    def __init__(self):
        self.inventory = {}

    def add_product(self, product_name, price, quantity):
        if product_name in self.inventory:
            self.inventory[product_name]['quantity'] += quantity
        else:
            self.inventory[product_name] = {'name': product_name, 'price': price, 'quantity': quantity}

    def remove_product(self, product_name):
        if product_name not in self.inventory:
            print("Product not found.")
        else:
            del self.inventory[product_name]

    def update_quantity(self, product_name, new_quantity):
        if product_name not in self.inventory:
            print("Product not found.")
        else:
            self.inventory[product_name]['quantity'] = new_quantity

    def display_inventory(self):
        print("Inventory:")
        for product in self.inventory.values():
            print(f"{product['name']} - Price: {product['price']} - Quantity: {product['quantity']}")

    def calculate_inventory_value(self):
        total_value = 0
        for product in self.inventory.values():
            total_value += product['price'] * product['quantity']
        return total_value
```

