```c++
#include <iostream>
#include <string>

using namespace std;

class ConsoleColor {
public:
    enum class Color {
        BLACK,
        RED,
        GREEN,
        BLUE,
        YELLOW,
        CYAN,
        WHITE
    };

    ConsoleColor(Color color) : color_(color) {}

    void setBackground(Color color) {
        background_ = color;
    }

    void setTextColor(Color color) {
        text_ = color;
    }

    void print() {
        cout << endl;
        cout << "Background: " << colorToString(background_) << endl;
        cout << "Text: " << colorToString(text_) << endl;
    }

private:
    Color color_;
    Color background_;
    Color text_;

    string colorToString(Color color) {
        switch (color) {
            case Color::BLACK:
                return "\033[0m";
            case Color::RED:
                return "\033[31m";
            // ... other colors ...
            default:
                return "\033[37m";
        }
    }
};

int main() {
    ConsoleColor console;

    cout << "Enter a color name or code (e.g. red, #FF0000): ";
    string input;
    cin >> input;

    try {
        console.setBackground(parseColor(input));
        console.setTextColor(parseColor(input));
        console.print();
    } catch (invalid_argument& e) {
        cout << "Invalid color input. Please enter a valid color name or code." << endl;
    }

    return 0;
}

Color parseColor(string input) {
    if (input.find('#') == 0) {
        return Color(fromHex(input.substr(1)));
    } else {
        return Color(static_cast<Color>(input));
    }
}

int fromHex(string hex) {
    if (hex.length() != 6) {
        throw invalid_argument("Invalid hex code. It should be 6 characters long.");
    }
    return stoi(hex, nullptr, 16);
}
```

**Explanation:**

* We defined a class `ConsoleColor` with methods to set the background and text colors.
* The `Color` enum defines the available color names.
* The `parseColor` function attempts to parse the user input into a `Color` value.
* The `fromHex` function converts a hex code to an integer value.
* In the `main` function, we read the user input and call the `setBackground` and `setTextColor` methods of the `ConsoleColor` object.
* If an invalid color input is detected, an `invalid_argument` exception is thrown.

