// Function to generate filter conditions
function generateFilterConditions($fields, $values)
{
    $conditions = [];
    foreach ($fields as $i => $field) {
        $conditions[] = "$field = ?";
        $values[] = $values[$i];
    }
    return implode(' AND ', $conditions);
}

