def get_repo_data(project, time):
    """
    Retrieves data from a GitHub repository using the GitHub GraphQL API.

    Args:
        project: The name of the project.
        time: A time parameter for filtering the data.

    Returns:
        A structured dictionary containing the retrieved repository data.
    """

    query = """
    query RepositoryData($project: String!, $time: DateTime!) {
        repository(owner: "YOUR_GITHUB_USERNAME", name: $project) {
            id
            name
            createdAt
            updatedAt
            releases(first: 100, after: $time) {
                edges {
                    node {
                        id
                        name
                        tag
                        createdAt
                    }
                }
            }
        }
    }
    """

    variables = {"project": project, "time": time}

    return run_query(query, variables)
```

