class File:
    def __init__(self, name, permission):
        self.name = name
        self.permission = permission

    def get_permission(self):
        return self.permission

    def set_permission(self, new_permission):
        if new_permission < 0 or new_permission > 4:
            raise ValueError("Permission level must be between 0 and 4.")
        self.permission = new_permission


class Directory:
    def __init__(self, name):
        self.name = name
        self.files = []

    def add_file(self, file):
        if any(f.name == file.name for f in self.files):
            raise ValueError("File already exists.")
        self.files.append(file)

    def get_files_with_permission(self, permission):
        return [f.name for f in self.files if f.get_permission() == permission]

    def get_file_permissions(self):
        return {f.name: f.get_permission() for f in self.files}

    def remove_file(self, file_name):
        if file_name not in [f.name for f in self.files]:
            raise ValueError("File not found.")
        self.files = [f for f in self.files if f.name != file_name]


# Demonstrate usage
file1 = File("file1.txt", 3)
file2 = File("file2.csv", 2)
file3 = File("file3.exe", 4)

directory = Directory("MyDirectory")
directory.add_file(file1)
directory.add_file(file2)
directory.add_file(file3)

# Get files with read and write access
read_write_files = directory.get_files_with_permission(3)
print(read_write_files)

# Get file permissions
file_permissions = directory.get_file_permissions()
print(file_permissions)

# Remove a file
directory.remove_file("file2.csv")
```

