public class ConcreteTableConverter implements Itbl {

    @Override
    public List<List<String>> convertToTable(Ivo vo) {
        // Get the fields of the value object
        List<String> fieldNames = getFieldValueNames(vo);

        // Create a table header
        List<String> tableHeader = List.of("Field", "Value");

        // Create a table body
